using Clock=chrono::steady_clock;
static int64_t nowms(){return chrono::duration_cast<chrono::milliseconds>(Clock::now().time_since_epoch()).count();}
static volatile sig_atomic_t hup=0;
static void onhup(int){hup=1;}
static string trim(string s){size_t a=0,b=s.size(); while(a<b&&(s[a]==' '||s[a]=='\t'||s[a]=='\r'))++a; while(b>a&&(s[b-1]==' '||s[b-1]=='\t'||s[b-1]=='\r'))--b;return s.substr(a,b-a);}
static string lower(string s){for(char &c:s)if(c>='A'&&c<='Z')c+=32;return s;}
static bool uintparse(string_view s,uint64_t &v){if(s.empty())return false;v=0;for(unsigned char c:s){if(c<'0'||c>'9'||v>(UINT64_MAX-(c-'0'))/10)return false;v=v*10+c-'0';}return true;}
static bool tokenchar(unsigned char c){return (c>='a'&&c<='z')||(c>='A'&&c<='Z')||(c>='0'&&c<='9')||strchr("!#$%&'*+-.^_`|~",c);}
static bool address(const string&s,sockaddr_in& a){auto p=s.rfind(':');if(p==string::npos)return false;uint64_t port;if(!uintparse(string_view(s).substr(p+1),port)||!port||port>65535)return false;string h=s.substr(0,p);memset(&a,0,sizeof(a));a.sin_family=AF_INET;a.sin_port=htons(port);return inet_pton(AF_INET,h.c_str(),&a.sin_addr)==1;}
struct Config{sockaddr_in listen{},origin{};string listenstr,root;int rootfd=-1;uint32_t trusted=0;uint64_t maxconn=0,header=0,headms=0,idlems=0,writems=0,maxreq=0,depth=0,cburst=0,gburst=0,refill=0;};
static bool config(const string&path,Config&c){ifstream f(path);if(!f)return false;unordered_map<string,string> m;string s;while(getline(f,s)){s=trim(s);if(s.empty()||s[0]=='#')continue;auto p=s.find('=');if(p==string::npos)return false;string k=trim(s.substr(0,p)),v=trim(s.substr(p+1));if(k.empty()||!m.emplace(k,v).second)return false;}static const vector<string> keys={"listen","root","max_connections","header_bytes","header_timeout_ms","idle_timeout_ms","write_timeout_ms","max_requests","pipeline_depth","origin_address","client_burst","global_burst","refill_ms","trusted_peer"};if(m.size()!=keys.size())return false;for(auto&k:keys)if(!m.count(k))return false;auto number=[&](const char*k,uint64_t&v){return uintparse(m[k],v)&&v>0&&v<=INT32_MAX;};if(!address(m["listen"],c.listen)||!address(m["origin_address"],c.origin)||inet_pton(AF_INET,m["trusted_peer"].c_str(),&c.trusted)!=1||!number("max_connections",c.maxconn)||!number("header_bytes",c.header)||!number("header_timeout_ms",c.headms)||!number("idle_timeout_ms",c.idlems)||!number("write_timeout_ms",c.writems)||!number("max_requests",c.maxreq)||!number("pipeline_depth",c.depth)||!number("client_burst",c.cburst)||!number("global_burst",c.gburst)||!number("refill_ms",c.refill))return false;c.listenstr=m["listen"];c.root=m["root"];if(c.root.empty()||c.root[0]!='/')return false;c.rootfd=open(c.root.c_str(),O_RDONLY|O_DIRECTORY|O_CLOEXEC);return c.rootfd>=0;}
static int listener(const sockaddr_in&a){int fd=socket(AF_INET,SOCK_STREAM|SOCK_NONBLOCK|SOCK_CLOEXEC,0);if(fd<0)return -1;int one=1;setsockopt(fd,SOL_SOCKET,SO_REUSEADDR,&one,sizeof(one));if(bind(fd,(const sockaddr*)&a,sizeof(a))||listen(fd,1024)){close(fd);return -1;}return fd;}
static bool utf8(const string&s){for(size_t i=0;i<s.size();){unsigned c=(unsigned char)s[i++];if(c<128)continue;unsigned n,min,v;if(c>=0xc2&&c<=0xdf){n=1;min=0x80;v=c&31;}else if(c>=0xe0&&c<=0xef){n=2;min=0x800;v=c&15;}else if(c>=0xf0&&c<=0xf4){n=3;min=0x10000;v=c&7;}else return false;if(i+n>s.size())return false;while(n--){unsigned x=(unsigned char)s[i++];if((x&0xc0)!=0x80)return false;v=(v<<6)|(x&63);}if(v<min||v>0x10ffff||(v>=0xd800&&v<=0xdfff))return false;}return true;}
static int hex(char c){if(c>='0'&&c<='9')return c-'0';if(c>='a'&&c<='f')return c-'a'+10;if(c>='A'&&c<='F')return c-'A'+10;return -1;}
static bool pathdecode(const string&target,string&rawpath,string&decoded){if(target.empty()||target[0]!='/'||target.find('#')!=string::npos)return false;for(unsigned char c:target)if(c<=32||c==127||c=='\\')return false;size_t q=target.find('?');rawpath=target.substr(0,q);for(size_t i=0;i<rawpath.size();i++){unsigned char c=rawpath[i];if(c=='%'){if(i+2>=rawpath.size())return false;int a=hex(rawpath[i+1]),b=hex(rawpath[i+2]);if(a<0||b<0)return false;c=(a<<4)|b;i+=2;}if(!c||c=='\\')return false;decoded.push_back(c);}return utf8(decoded);}
static bool dotdot(const string&s){size_t p=0;while(p<s.size()){while(p<s.size()&&s[p]=='/')p++;size_t e=s.find('/',p);if(e==string::npos)e=s.size();if(s.substr(p,e-p)=="..")return true;p=e;}return false;}
static int getfile(int root,const string&path,int&status,uint64_t&len){int d=dup(root);if(d<0){status=500;return -1;}size_t p=0;vector<string> parts;while(p<path.size()){while(p<path.size()&&path[p]=='/')p++;size_t e=path.find('/',p);if(e==string::npos)e=path.size();if(e>p&&path.substr(p,e-p)!=".")parts.push_back(path.substr(p,e-p));p=e;}if(parts.empty()){close(d);status=403;return -1;}for(size_t i=0;i<parts.size();i++){struct stat st;if(fstatat(d,parts[i].c_str(),&st,AT_SYMLINK_NOFOLLOW)<0){status=(errno==ENOENT||errno==ENOTDIR)?404:403;close(d);return -1;}if(S_ISLNK(st.st_mode)){status=403;close(d);return -1;}bool last=i+1==parts.size();if((!last&&!S_ISDIR(st.st_mode))||(last&&!S_ISREG(st.st_mode))){status=403;close(d);return -1;}int fd=openat(d,parts[i].c_str(),O_RDONLY|O_CLOEXEC|O_NOFOLLOW|O_NONBLOCK|(last?0:O_DIRECTORY));close(d);if(fd<0){status=(errno==ENOENT||errno==ENOTDIR)?404:403;return -1;}d=fd;if(last){if(fstat(d,&st)||!S_ISREG(st.st_mode)){close(d);status=403;return -1;}if(!path.empty()&&path.back()=='/'){close(d);status=403;return -1;}len=st.st_size;status=200;return d;}}close(d);status=404;return -1;}
struct Bucket{double tokens=0;int64_t at=0;};
struct Conn{int fd=-1,up=-1,file=-1;uint32_t peer=0;string in,out,upreq,uphead;size_t outpos=0,upreqpos=0;uint64_t nreq=0,fileleft=0,upleft=0;off_t fileoff=0;int state=0;bool closeafter=false,head=false,upheader=false,upconnected=false;int64_t since=0,idle=0,progress=0,upactivity=0;};
struct Request{string method,target,rawpath,path,host,real;bool close=false;int hosts=0,reals=0;};
static bool has_token(const string&s,const string&needle){size_t p=0;while(p<=s.size()){size_t e=s.find(',',p);if(e==string::npos)e=s.size();if(lower(trim(s.substr(p,e-p)))==needle)return true;if(e==s.size())break;p=e+1;}return false;}
static bool parse_req(const string&h,Request&r){size_t e=h.find("\r\n");if(e==string::npos)return false;string line=h.substr(0,e);size_t a=line.find(' '),b=a==string::npos?string::npos:line.find(' ',a+1);if(a==string::npos||b==string::npos||a==0||b==a+1||line.find(' ',b+1)!=string::npos)return false;r.method=line.substr(0,a);for(unsigned char c:r.method)if(!tokenchar(c))return false;r.target=line.substr(a+1,b-a-1);string ver=line.substr(b+1);if(ver!="HTTP/1.1"&&ver!="HTTP/1.0")return false;r.close=ver=="HTTP/1.0";if(!pathdecode(r.target,r.rawpath,r.path))return false;int cl=0;bool te=false;size_t p=e+2;while(p<h.size()){e=h.find("\r\n",p);if(e==string::npos)return false;if(e==p)break;string_view l(h.data()+p,e-p);size_t c=l.find(':');if(c==string_view::npos||!c)return false;for(size_t i=0;i<c;i++)if(!tokenchar((unsigned char)l[i]))return false;for(size_t i=c+1;i<l.size();i++){unsigned char x=l[i];if((x<32&&x!='\t')||x==127)return false;}string key=lower(string(l.substr(0,c))),val=trim(string(l.substr(c+1)));if(key=="connection"&&has_token(val,"close"))r.close=true;else if(key=="host"){r.host=val;r.hosts++;}else if(key=="x-real-ip"){r.real=val;r.reals++;}else if(key=="content-length"){uint64_t v;cl++;if(!uintparse(val,v)||v!=0)return false;}else if(key=="transfer-encoding")te=true;p=e+2;}return cl<=1&&!te;}
static string reason(int s){switch(s){case 200:return "OK";case 400:return "Bad Request";case 403:return "Forbidden";case 404:return "Not Found";case 405:return "Method Not Allowed";case 429:return "Too Many Requests";case 431:return "Request Header Fields Too Large";case 500:return "Internal Server Error";case 502:return "Bad Gateway";default:return "Response";}}
class Server{public:Config cfg;string configpath;int ep=-1,lfd=-1;unordered_map<int,Conn*> clients,ups;unordered_map<uint32_t,Bucket> buckets;Bucket global;int64_t lastgc=0;Server(Config c,string p):cfg(c),configpath(p){global={double(c.gburst),nowms()};}
void ctl(int op,int fd,uint32_t ev){epoll_event e{};e.events=ev;e.data.fd=fd;epoll_ctl(ep,op,fd,&e);}
void closeup(Conn*c){if(c->up>=0){ctl(EPOLL_CTL_DEL,c->up,0);ups.erase(c->up);close(c->up);c->up=-1;}}
void destroy(Conn*c){closeup(c);if(c->file>=0)close(c->file);ctl(EPOLL_CTL_DEL,c->fd,0);clients.erase(c->fd);close(c->fd);delete c;}
void update(Conn*c){uint32_t ev=0;if(c->state==0)ev|=EPOLLIN|EPOLLRDHUP;else if(c->outpos<c->out.size()||c->fileleft)ev|=EPOLLOUT;ctl(EPOLL_CTL_MOD,c->fd,ev);if(c->up>=0){uint32_t ue=EPOLLRDHUP;if(c->upreqpos<c->upreq.size()||!c->upconnected)ue|=EPOLLOUT;else if(!c->upheader||c->out.size()-c->outpos<131072)ue|=EPOLLIN;ctl(EPOLL_CTL_MOD,c->up,ue);}}
string hdr(int status,uint64_t len,bool close,const string&extra=""){return "HTTP/1.1 "+to_string(status)+" "+reason(status)+"\r\nContent-Length: "+to_string(len)+"\r\nConnection: "+(close?"close":"keep-alive")+"\r\n"+extra+"\r\n";}
void simple(Conn*c,int status,const string&body="",bool malformed=false){closeup(c);if(c->file>=0){close(c->file);c->file=-1;c->fileleft=0;}if(malformed)c->closeafter=true;c->state=1;c->out=hdr(status,body.size(),c->closeafter,status==405?"Allow: GET, HEAD\r\n":"");if(!c->head)c->out+=body;c->outpos=0;c->progress=nowms();update(c);}
bool admit(uint32_t key,int64_t t){auto [it,ins]=buckets.try_emplace(key,Bucket{double(cfg.cburst),t});auto refill=[&](Bucket&b,uint64_t cap){b.tokens=min(double(cap),b.tokens+double(max<int64_t>(0,t-b.at))/double(cfg.refill));b.at=t;};refill(global,cfg.gburst);refill(it->second,cfg.cburst);if(global.tokens<1.0||it->second.tokens<1.0)return false;global.tokens-=1;it->second.tokens-=1;return true;}
void startproxy(Conn*c,const Request&r){int fd=socket(AF_INET,SOCK_STREAM|SOCK_NONBLOCK|SOCK_CLOEXEC,0);if(fd<0){simple(c,502);return;}int z=connect(fd,(sockaddr*)&cfg.origin,sizeof(cfg.origin));if(z<0&&errno!=EINPROGRESS){close(fd);simple(c,502);return;}c->up=fd;c->state=2;c->upconnected=z==0;c->upheader=false;c->uphead.clear();c->upleft=0;c->upreq=r.method+" "+r.target.substr(8)+" HTTP/1.1\r\nHost: "+r.host+"\r\nConnection: close\r\n\r\n";c->upreqpos=0;c->out.clear();c->outpos=0;c->upactivity=c->progress=nowms();ups[fd]=c;ctl(EPOLL_CTL_ADD,fd,EPOLLOUT|EPOLLRDHUP);update(c);}
void process(Conn*c){if(c->state!=0)return;size_t end=c->in.find("\r\n\r\n");size_t bad=string::npos;for(size_t i=0;i<c->in.size();i++){unsigned char x=c->in[i];if(x==0||(x=='\n'&&(i==0||c->in[i-1]!='\r'))||(x=='\r'&&i+1<c->in.size()&&c->in[i+1]!='\n')){bad=i;break;}if(end!=string::npos&&i>=end+3)break;}if(bad!=string::npos){c->head=false;c->nreq++;simple(c,400,"",true);return;}if(end==string::npos){if(c->in.size()>cfg.header){c->head=false;c->nreq++;simple(c,431,"",true);}return;}size_t total=end+4;if(total>cfg.header){c->head=false;c->nreq++;simple(c,431,"",true);return;}string h=c->in.substr(0,total);c->in.erase(0,total);c->since=c->in.empty()?0:nowms();Request r;c->nreq++;if(!parse_req(h,r)){c->head=false;simple(c,400,"",true);return;}c->head=r.method=="HEAD";c->closeafter=r.close||c->nreq>=cfg.maxreq;if(r.method!="GET"&&r.method!="HEAD"){simple(c,405);return;}if(r.method=="GET"&&r.path=="/health"){simple(c,200,"ok\n");return;}if(r.rawpath.rfind("/gateway/",0)==0){if(r.hosts!=1||r.host.empty()){simple(c,400,"",true);return;}uint32_t key=c->peer;if(c->peer==cfg.trusted&&r.reals==1){uint32_t ip;if(inet_pton(AF_INET,r.real.c_str(),&ip)==1)key=ip;}if(!admit(key,nowms())){simple(c,429);return;}startproxy(c,r);return;}if(dotdot(r.path)){simple(c,403);return;}int st;uint64_t size=0;int file=getfile(cfg.rootfd,r.path,st,size);if(file<0){simple(c,st);return;}c->state=1;c->out=hdr(200,size,c->closeafter,"Content-Type: application/octet-stream\r\n");c->outpos=0;c->progress=nowms();if(c->head){close(file);c->file=-1;c->fileleft=0;}else{c->file=file;c->fileleft=size;c->fileoff=0;if(!size){close(file);c->file=-1;}}update(c);}
void readclient(Conn*c){char buf[8192];while(c->state==0){size_t limit=cfg.header+1;if(c->in.size()>=limit){process(c);break;}size_t n=min(sizeof(buf),limit-c->in.size());ssize_t z=recv(c->fd,buf,n,0);if(z>0){int64_t t=nowms();if(c->in.empty())c->since=t;c->idle=t;c->in.append(buf,z);process(c);if(c->state!=0)break;}else if(z==0){destroy(c);return;}else if(errno==EAGAIN||errno==EWOULDBLOCK)break;else if(errno!=EINTR){destroy(c);return;}}if(clients.count(c->fd))update(c);}
void done(Conn*c){if(c->file>=0){close(c->file);c->file=-1;}if(c->closeafter){destroy(c);return;}c->state=0;c->out.clear();c->outpos=0;c->idle=nowms();if(!c->in.empty()){if(!c->since)c->since=c->idle;process(c);}update(c);}
void writeclient(Conn*c){while(c->outpos<c->out.size()){ssize_t n=send(c->fd,c->out.data()+c->outpos,c->out.size()-c->outpos,MSG_NOSIGNAL);if(n>0){c->outpos+=n;c->progress=nowms();}else if(n<0&&errno==EINTR)continue;else if(n<0&&(errno==EAGAIN||errno==EWOULDBLOCK)){update(c);return;}else{destroy(c);return;}}if(c->outpos==c->out.size()){c->out.clear();c->outpos=0;}while(c->fileleft){ssize_t n=sendfile(c->fd,c->file,&c->fileoff,min<uint64_t>(c->fileleft,1<<20));if(n>0){c->fileleft-=n;c->progress=nowms();}else if(n<0&&errno==EINTR)continue;else if(n<0&&(errno==EAGAIN||errno==EWOULDBLOCK)){update(c);return;}else{destroy(c);return;}}if(c->state==1){done(c);return;}update(c);}
bool parseup(Conn*c){auto e=c->uphead.find("\r\n\r\n");if(e==string::npos)return false;string h=c->uphead.substr(0,e+4),body=c->uphead.substr(e+4);c->uphead.clear();size_t le=h.find("\r\n");string line=h.substr(0,le);if(line.size()<12||(line.compare(0,9,"HTTP/1.1 ")&&line.compare(0,9,"HTTP/1.0 "))||line[9]<'1'||line[9]>'5'||line[10]<'0'||line[10]>'9'||line[11]<'0'||line[11]>'9'||(line.size()>12&&line[12]!=' ')){simple(c,502);return true;}int status=(line[9]-'0')*100+(line[10]-'0')*10+line[11]-'0';if(status<200){simple(c,502);return true;}vector<pair<string,string>> fields;uint64_t len=0;int cls=0;bool bad=false;string connection;size_t p=le+2;while(p<h.size()){size_t q=h.find("\r\n",p);if(q==string::npos){bad=true;break;}if(q==p)break;string l=h.substr(p,q-p);size_t x=l.find(':');if(x==string::npos||!x){bad=true;break;}for(size_t i=0;i<x;i++)if(!tokenchar((unsigned char)l[i]))bad=true;for(size_t i=x+1;i<l.size();i++){unsigned char ch=l[i];if((ch<32&&ch!='\t')||ch==127)bad=true;}string k=lower(l.substr(0,x)),v=trim(l.substr(x+1));if(k=="content-length"){cls++;if(!uintparse(v,len))bad=true;}else if(k=="transfer-encoding")bad=true;else if(k=="connection")connection+=","+v;fields.push_back({k,v});p=q+2;}if(bad||cls!=1){simple(c,502);return true;}string extra;for(auto&kv:fields){auto&k=kv.first;if(k=="content-length"||k=="connection"||k=="keep-alive"||k=="proxy-connection"||k=="transfer-encoding"||k=="upgrade"||k=="te"||k=="trailer"||has_token(connection,k))continue;extra+=k+": "+kv.second+"\r\n";}c->out=hdr(status,len,c->closeafter,extra);c->outpos=0;c->upheader=true;c->upleft=c->head?0:len;if(body.size()>c->upleft)body.resize(c->upleft);c->out+=body;c->upleft-=body.size();if(c->upleft==0){closeup(c);c->state=1;}c->progress=nowms();update(c);return true;}
void upevent(Conn*c,uint32_t ev){if(!c->upconnected&&(ev&(EPOLLOUT|EPOLLERR|EPOLLHUP))){int err=0;socklen_t n=sizeof(err);if(getsockopt(c->up,SOL_SOCKET,SO_ERROR,&err,&n)<0||err){simple(c,502);return;}c->upconnected=true;}while(c->up>=0&&c->upreqpos<c->upreq.size()&&c->upconnected){ssize_t n=send(c->up,c->upreq.data()+c->upreqpos,c->upreq.size()-c->upreqpos,MSG_NOSIGNAL);if(n>0){c->upreqpos+=n;c->upactivity=nowms();}else if(n<0&&errno==EINTR)continue;else if(n<0&&(errno==EAGAIN||errno==EWOULDBLOCK))break;else{simple(c,502);return;}}if(c->up<0)return;if(c->upreqpos==c->upreq.size()&&(ev&(EPOLLIN|EPOLLRDHUP|EPOLLHUP|EPOLLERR))){char buf[16384];while(c->up>=0&&(!c->upheader||c->out.size()-c->outpos<131072)){ssize_t n=recv(c->up,buf,sizeof(buf),0);if(n>0){c->upactivity=nowms();if(!c->upheader){c->uphead.append(buf,n);if(c->uphead.size()>65536&&c->uphead.find("\r\n\r\n")==string::npos){simple(c,502);return;}parseup(c);}else{size_t m=min<uint64_t>(n,c->upleft);if(c->outpos>65536){c->out.erase(0,c->outpos);c->outpos=0;}c->out.append(buf,m);c->upleft-=m;if(!c->upleft){closeup(c);c->state=1;}}}else if(n==0){if(!c->upheader){simple(c,502);return;}if(c->upleft){destroy(c);return;}closeup(c);c->state=1;break;}else if(errno==EINTR)continue;else if(errno==EAGAIN||errno==EWOULDBLOCK)break;else{if(!c->upheader)simple(c,502);else destroy(c);return;}}}update(c);}
void reload(){Config next;if(!config(configpath,next))return;int newfd=lfd;if(next.listenstr!=cfg.listenstr){newfd=listener(next.listen);if(newfd<0){close(next.rootfd);return;}ctl(EPOLL_CTL_ADD,newfd,EPOLLIN);}if(newfd!=lfd){ctl(EPOLL_CTL_DEL,lfd,0);close(lfd);lfd=newfd;}close(cfg.rootfd);cfg=next;buckets.clear();global={double(cfg.gburst),nowms()};}
int run(){lfd=listener(cfg.listen);if(lfd<0)return 1;ep=epoll_create1(EPOLL_CLOEXEC);if(ep<0)return 1;ctl(EPOLL_CTL_ADD,lfd,EPOLLIN);array<epoll_event,1024> events;int64_t tick=nowms();for(;;){int n=epoll_wait(ep,events.data(),events.size(),50);if(hup){hup=0;reload();}if(n<0&&errno!=EINTR)break;for(int i=0;i<n;i++){int fd=events[i].data.fd;uint32_t ev=events[i].events;if(fd==lfd){for(;;){sockaddr_in peer{};socklen_t sz=sizeof(peer);int x=accept4(lfd,(sockaddr*)&peer,&sz,SOCK_NONBLOCK|SOCK_CLOEXEC);if(x<0){if(errno==EINTR)continue;break;}if(clients.size()>=cfg.maxconn){close(x);continue;}Conn*c=new Conn;c->fd=x;c->peer=peer.sin_addr.s_addr;c->idle=nowms();clients[x]=c;ctl(EPOLL_CTL_ADD,x,EPOLLIN|EPOLLRDHUP);}continue;}auto ci=clients.find(fd);if(ci!=clients.end()){Conn*c=ci->second;if(ev&EPOLLERR){destroy(c);continue;}if(c->state==0&&(ev&(EPOLLIN|EPOLLRDHUP|EPOLLHUP))){readclient(c);continue;}if(c->state!=0&&(ev&EPOLLOUT)){writeclient(c);continue;}if(ev&(EPOLLRDHUP|EPOLLHUP)){destroy(c);continue;}}else{auto ui=ups.find(fd);if(ui!=ups.end())upevent(ui->second,ev);}}int64_t t=nowms();if(t-tick>=50){tick=t;vector<Conn*> dead,fail;for(auto&kv:clients){Conn*c=kv.second;if(c->state==0){if((c->since&&t-c->since>=(int64_t)cfg.headms)||(!c->since&&t-c->idle>=(int64_t)cfg.idlems))dead.push_back(c);}else if(c->state==2&&c->up>=0&&t-c->upactivity>=(int64_t)cfg.writems&&(!c->upheader||c->out.size()-c->outpos<131072)){if(!c->upheader)fail.push_back(c);else dead.push_back(c);}else if((c->outpos<c->out.size()||c->fileleft)&&t-c->progress>=(int64_t)cfg.writems)dead.push_back(c);}for(Conn*c:fail)simple(c,502);for(Conn*c:dead)destroy(c);if(buckets.size()>65536&&t-lastgc>1000){lastgc=t;for(auto it=buckets.begin();it!=buckets.end();)if(double(t-it->second.at)/cfg.refill>=cfg.cburst)it=buckets.erase(it);else ++it;}}}return 1;}};
int main(int argc,char**argv){if(argc!=3||string(argv[1])!="--config")return 1;Config c;if(!config(argv[2],c))return 1;signal(SIGPIPE,SIG_IGN);struct sigaction sa{};sa.sa_handler=onhup;sigemptyset(&sa.sa_mask);sigaction(SIGHUP,&sa,nullptr);Server s(c,argv[2]);return s.run();}
